import { MakeLogicType, kea, path, reducers } from 'kea'

// Toolbar shim — no feature flags available in toolbar context
// eslint-disable-next-line @typescript-eslint/no-unused-vars
export function getFeatureFlagPayload(_flag: string): undefined {
    return undefined
}

// The toolbar never runs against a self-hosted PERSISTED_FEATURE_FLAGS baseline, so client-resolved
// flags are always honored there.
export function areClientFeatureFlagsHonored(): boolean {
    return true
}

export const FEATURE_PREVIEW_SELF_HOSTED_DISABLED_REASON = ''

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface featureFlagLogicValues {
    featureFlags: Record<string, boolean | string>
}

export type featureFlagLogicType = MakeLogicType<featureFlagLogicValues, {}>

export const featureFlagLogic = kea<featureFlagLogicType>([
    path(['toolbar', 'shims', 'featureFlagLogic']),
    reducers({
        featureFlags: [{} as Record<string, string | boolean>, {}],
    }),
])
